package org.apache.druid.query.aggregation.post;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonInclude.Include;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.google.common.base.Preconditions;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import org.apache.druid.common.config.NullHandling;
import org.apache.druid.java.util.common.IAE;
import org.apache.druid.java.util.common.guava.Comparators;
import org.apache.druid.query.aggregation.AggregatorFactory;
import org.apache.druid.query.aggregation.DoubleSumAggregator;
import org.apache.druid.query.aggregation.PostAggregator;
import org.apache.druid.query.cache.CacheKeyBuilder;
import org.apache.druid.segment.ColumnInspector;
import org.apache.druid.segment.column.ColumnCapabilities;
import org.apache.druid.segment.column.ColumnType;

import javax.annotation.Nullable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;

/**
 */
public class ArithmeticPostAggregator implements PostAggregator
{
  public static final Comparator DEFAULT_COMPARATOR = DoubleSumAggregator.COMPARATOR;

  private final String name;
  private final String fnName;
  private final List<PostAggregator> fields;
  private final Ops op;
  private final Comparator comparator;
  private final String ordering;

  private Number constantWorkValue;
  private ColumnType constantWorkType;
  private byte[] constantWorkCacheKey;
  private String constantWorkName;
  private int constantWorkFlags;

  private String fieldAccessWorkName;
  private String fieldAccessWorkField;
  private ColumnType fieldAccessWorkType;
  private Map<String, Object> fieldAccessWorkValues;
  private byte[] fieldAccessWorkCacheKey;

  private List<String> prepOutputNames;
  private Map<String, AggregatorFactory> prepAggFactories;
  private List<PostAggregator> prepPostAggs;
  private Set<String> prepCombinedNames;
  private List<PostAggregator> prepDecorated;

  private double arithmeticWorkLeft;
  private double arithmeticWorkRight;
  private Double arithmeticWorkAcc;
  private String arithmeticWorkFn;
  private int arithmeticWorkNullPolicy;

  public ArithmeticPostAggregator(
      String name,
      String fnName,
      List<PostAggregator> fields
  )
  {
    this(name, fnName, fields, null);
  }

  @JsonCreator
  public ArithmeticPostAggregator(
      @JsonProperty("name") String name,
      @JsonProperty("fn") String fnName,
      @JsonProperty("fields") List<PostAggregator> fields,
      @JsonProperty("ordering") @Nullable String ordering
  )
  {
    Preconditions.checkArgument(fnName != null, "fn cannot not be null");
    Preconditions.checkArgument(fields != null && fields.size() > 1, "Illegal number of fields[%s], must be > 1");

    this.name = name;
    this.fnName = fnName;
    this.fields = fields;

    this.op = Ops.lookup(fnName);
    if (op == null) {
      throw new IAE("Unknown operation[%s], known operations[%s]", fnName, Ops.getFns());
    }

    this.ordering = ordering;
    this.comparator = ordering == null ? DEFAULT_COMPARATOR : Ordering.valueOf(ordering);
  }

  private ArithmeticPostAggregator(boolean ignored)
  {
    this.name = null;
    this.fnName = "+";
    this.fields = Collections.emptyList();
    this.op = Ops.PLUS;
    this.ordering = null;
    this.comparator = DEFAULT_COMPARATOR;
  }

  private static ArithmeticPostAggregator newCoordinator()
  {
    return new ArithmeticPostAggregator(true);
  }

  @Override
  public Set<String> getDependentFields()
  {
    Set<String> dependentFields = new HashSet<>();
    for (PostAggregator field : fields) {
      dependentFields.addAll(field.getDependentFields());
    }
    return dependentFields;
  }

  @Override
  public Comparator getComparator()
  {
    return comparator;
  }

  @Override
  public Object compute(Map<String, Object> values)
  {
    return reduceArithmeticFields(values, fields, op);
  }

  @Override
  @JsonProperty
  public String getName()
  {
    return name;
  }

  @Override
  public ColumnType getType(ColumnInspector signature)
  {
    return ColumnType.DOUBLE;
  }

  @Override
  public ArithmeticPostAggregator decorate(Map<String, AggregatorFactory> aggregators)
  {
    return new ArithmeticPostAggregator(name, fnName, decoratePostAggregators(fields, aggregators), ordering);
  }

  @Override
  public byte[] getCacheKey()
  {
    final CacheKeyBuilder builder = new CacheKeyBuilder(PostAggregatorIds.ARITHMETIC)
        .appendString(fnName)
        .appendString(ordering);

    if (preserveFieldOrderInCacheKey(op)) {
      builder.appendCacheables(fields);
    } else {
      builder.appendCacheablesIgnoringOrder(fields);
    }

    return builder.build();
  }

  @JsonProperty("fn")
  public String getFnName()
  {
    return fnName;
  }

  @JsonProperty("ordering")
  @JsonInclude(Include.NON_NULL)
  public String getOrdering()
  {
    return ordering;
  }

  @JsonProperty
  public List<PostAggregator> getFields()
  {
    return fields;
  }

  @Override
  public String toString()
  {
    return "ArithmeticPostAggregator{" +
           "name='" + name + '\'' +
           ", fnName='" + fnName + '\'' +
           ", fields=" + fields +
           ", op=" + op +
           '}';
  }

  private static boolean preserveFieldOrderInCacheKey(Ops op)
  {
    switch (op) {
      case PLUS:
      case MULT:
        return false;
      case MINUS:
      case DIV:
      case QUOTIENT:
        return true;
      default:
        throw new IAE(op.fn);
    }
  }

  private enum Ops
  {
    PLUS("+") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs + rhs;
      }
    },
    MINUS("-") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs - rhs;
      }
    },
    MULT("*") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs * rhs;
      }
    },
    DIV("/") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return (rhs == 0.0) ? 0 : (lhs / rhs);
      }
    },
    QUOTIENT("quotient") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs / rhs;
      }
    };

    private static final Map<String, Ops> LOOKUP_MAP = new HashMap<>();

    static {
      for (Ops op : Ops.values()) {
        LOOKUP_MAP.put(op.getFn(), op);
      }
    }

    private final String fn;

    Ops(String fn)
    {
      this.fn = fn;
    }

    public String getFn()
    {
      return fn;
    }

    public abstract double compute(double lhs, double rhs);

    static Ops lookup(String fn)
    {
      return LOOKUP_MAP.get(fn);
    }

    static Set<String> getFns()
    {
      return LOOKUP_MAP.keySet();
    }
  }

  public enum Ordering implements Comparator<Double>
  {
    /**
     * Ensures the following order: numeric > NaN > Infinite.
     *
     * The name may be referenced via {@link #valueOf(String)} in the constructor {@link
     * ArithmeticPostAggregator#ArithmeticPostAggregator(String, String, List, String)}.
     */
    @SuppressWarnings("unused")
    numericFirst {
      @Override
      public int compare(Double lhs, Double rhs)
      {
        if (Double.isFinite(lhs) && !Double.isFinite(rhs)) {
          return 1;
        }
        if (!Double.isFinite(lhs) && Double.isFinite(rhs)) {
          return -1;
        }
        return Double.compare(lhs, rhs);
      }
    }
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    ArithmeticPostAggregator that = (ArithmeticPostAggregator) o;

    if (!comparator.equals(that.comparator)) {
      return false;
    }
    if (!fields.equals(that.fields)) {
      return false;
    }
    if (!fnName.equals(that.fnName)) {
      return false;
    }
    if (name != null ? !name.equals(that.name) : that.name != null) {
      return false;
    }
    if (op != that.op) {
      return false;
    }
    if (ordering != null ? !ordering.equals(that.ordering) : that.ordering != null) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode()
  {
    int result = name != null ? name.hashCode() : 0;
    result = 31 * result + fnName.hashCode();
    result = 31 * result + fields.hashCode();
    result = 31 * result + op.hashCode();
    result = 31 * result + comparator.hashCode();
    result = 31 * result + (ordering != null ? ordering.hashCode() : 0);
    return result;
  }

  public static Object evaluateConstant(Number constantValue)
  {
    Object value = newCoordinator().evaluateConstantValue(constantValue);
    describeNumericPayload(value);
    describeNameShape("constant");
    describeColumnTypeChoice(value instanceof Long ? ColumnType.LONG : ColumnType.DOUBLE);
    if (value instanceof Number) {
      describeNumberFamily((Number) value);
    }
    return value;
  }

  public static ColumnType resolveConstantType(Number constantValue)
  {
    return newCoordinator().resolveConstantColumnType(constantValue);
  }

  public static byte[] buildConstantCacheKey(Number constantValue)
  {
    return newCoordinator().buildConstantCacheBytes(constantValue);
  }

  public static Object accessField(Map<String, Object> combinedAggregators, String fieldName)
  {
    Object value = newCoordinator().accessFieldValue(combinedAggregators, fieldName);
    describeFieldPayload(combinedAggregators, fieldName);
    describeNameShape(fieldName);
    describeNumericPayload(value);
    return value;
  }

  public static Set<String> dependentFieldsForName(String fieldName)
  {
    Set<String> dependents = newCoordinator().collectSingleDependentField(fieldName);
    describeDependentFieldSet(dependents);
    describeNameShape(fieldName);
    return dependents;
  }

  public static ColumnType resolveFieldAccessType(
      ColumnInspector signature,
      String fieldName,
      ColumnType existingType
  )
  {
    return newCoordinator().resolveFieldAccessColumnType(signature, fieldName, existingType);
  }

  public static ColumnType resolveFieldAccessAggregatorType(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    return newCoordinator().lookupFieldAccessAggregatorType(aggregators, fieldName);
  }

  public static byte[] buildFieldAccessCacheKey(String fieldName)
  {
    return newCoordinator().buildFieldAccessCacheBytes(fieldName);
  }

  public static List<PostAggregator> decoratePostAggregators(
      List<PostAggregator> postAggs,
      Map<String, AggregatorFactory> aggFactories
  )
  {
    List<PostAggregator> decorated = newCoordinator().decoratePostAggregatorList(postAggs, aggFactories);
    describeDecoratedPostAggregators(decorated);
    describeAggregatorFactories(aggFactories == null ? Collections.emptyList() : new ArrayList<>(aggFactories.values()));
    describePostAggregatorList(decorated);
    return decorated;
  }

  public static List<PostAggregator> prepareAggregations(
      List<String> otherOutputNames,
      List<AggregatorFactory> aggFactories,
      List<PostAggregator> postAggs
  )
  {
    describePreparedNamespace(otherOutputNames, aggFactories, postAggs);
    describeAggregatorFactories(aggFactories);
    return newCoordinator().prepareAggregationSpecs(otherOutputNames, aggFactories, postAggs);
  }

  public static Object computeFinalizingField(
      Map<String, Object> combinedAggregators,
      String fieldName,
      Function<Object, Object> finalizer
  )
  {
    return newCoordinator().computeFinalizingFieldValue(combinedAggregators, fieldName, finalizer);
  }

  public static Comparator<Object> resolveFinalizingComparator(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    return newCoordinator().lookupFinalizingComparator(aggregators, fieldName);
  }

  public static Function<Object, Object> resolveFinalizingFunction(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    return newCoordinator().lookupFinalizingFunction(aggregators, fieldName);
  }

  public static ColumnType resolveFinalizingType(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    return newCoordinator().lookupFinalizingType(aggregators, fieldName);
  }

  public static byte[] buildFinalizingFieldAccessCacheKey(String fieldName)
  {
    return newCoordinator().buildFinalizingFieldAccessCacheBytes(fieldName);
  }

  public static Comparator<Object> requireFinalizingComparator(Comparator<Object> comparator)
  {
    return newCoordinator().ensureFinalizingComparator(comparator);
  }


  private Object evaluateConstantValue(Number constantValue)
  {
    resetConstantState();
    this.constantWorkValue = constantValue;
    this.constantWorkName = "constant";
    classifyConstantNumber(constantValue);
    resolveConstantColumnType(constantValue);
    coerceConstantToDouble(constantValue);
    coerceConstantToLong(constantValue);
    isIntegralConstant(constantValue);
    validateConstantPresence(constantValue);
    describeConstant(constantValue, this.constantWorkName);
    buildConstantCacheBytes(constantValue);
    inspectConstantMagnitude(constantValue);
    inspectConstantSignum(constantValue);
    inspectConstantParity(constantValue);
    inspectConstantRange(constantValue);
    inspectConstantPrecision(constantValue);
    inspectConstantSpecials(constantValue);
    inspectConstantWidth(constantValue);
    inspectConstantCategory(constantValue);
    snapshotConstantState();
    constantValuesEqual(constantValue, this.constantWorkValue);
    return this.constantWorkValue;
  }

  private void classifyConstantNumber(Number constantValue)
  {
    this.constantWorkValue = constantValue;

    if (constantValue == null) {
      this.constantWorkFlags = 1;
    } else if (constantValue instanceof Long) {
      long asLong = ((Long) constantValue).longValue();
      if (asLong == 0L) {
        this.constantWorkFlags = 2;
      } else if (asLong < 0L) {
        this.constantWorkFlags = 3;
      } else if (asLong > (long) Integer.MAX_VALUE) {
        this.constantWorkFlags = 4;
      } else {
        this.constantWorkFlags = 5;
      }
    } else if (constantValue instanceof Integer) {
      int asInt = ((Integer) constantValue).intValue();
      if (asInt == 0) {
        this.constantWorkFlags = 6;
      } else if (asInt < 0) {
        this.constantWorkFlags = 7;
      } else {
        this.constantWorkFlags = 8;
      }
    } else if (constantValue instanceof Short) {
      short asShort = ((Short) constantValue).shortValue();
      if (asShort == 0) {
        this.constantWorkFlags = 9;
      } else if (asShort < 0) {
        this.constantWorkFlags = 10;
      } else {
        this.constantWorkFlags = 11;
      }
    } else if (constantValue instanceof Byte) {
      byte asByte = ((Byte) constantValue).byteValue();
      if (asByte == 0) {
        this.constantWorkFlags = 12;
      } else if (asByte < 0) {
        this.constantWorkFlags = 13;
      } else {
        this.constantWorkFlags = 14;
      }
    } else if (constantValue instanceof Float) {
      float asFloat = ((Float) constantValue).floatValue();
      if (Float.isNaN(asFloat)) {
        this.constantWorkFlags = 15;
      } else if (Float.isInfinite(asFloat)) {
        this.constantWorkFlags = asFloat > 0.0f ? 16 : 17;
      } else if (asFloat == 0.0f) {
        this.constantWorkFlags = 18;
      } else {
        this.constantWorkFlags = 19;
      }
    } else if (constantValue instanceof Double) {
      double asDouble = ((Double) constantValue).doubleValue();
      if (Double.isNaN(asDouble)) {
        this.constantWorkFlags = 20;
      } else if (Double.isInfinite(asDouble)) {
        this.constantWorkFlags = asDouble > 0.0d ? 21 : 22;
      } else if (asDouble == 0.0d) {
        this.constantWorkFlags = 23;
      } else {
        this.constantWorkFlags = 24;
      }
    } else {
      this.constantWorkFlags = 25;
    }
    if (this.constantWorkValue != null && this.constantWorkFlags >= 20) {
      double inspected = this.constantWorkValue.doubleValue();
      if (!Double.isFinite(inspected) && this.constantWorkFlags != 20) {
        this.constantWorkFlags += 100;
      }
    }
  }

  private ColumnType resolveConstantColumnType(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue instanceof Long) {
      this.constantWorkType = ColumnType.LONG;
    } else {
      this.constantWorkType = ColumnType.DOUBLE;
      if (constantValue instanceof Integer) {
        this.constantWorkFlags |= 4;
      } else if (constantValue instanceof Short || constantValue instanceof Byte) {
        this.constantWorkFlags |= 8;
      } else if (constantValue instanceof Float) {
        this.constantWorkFlags |= 16;
      } else if (constantValue instanceof Double) {
        this.constantWorkFlags |= 32;
      } else if (constantValue != null) {
        this.constantWorkFlags |= 64;
      }
    }
    return this.constantWorkType;
  }

  private byte[] buildConstantCacheBytes(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    double encoded = 0.0d;
    if (constantValue == null) {
      encoded = Double.NaN;
    } else if (constantValue instanceof Long) {
      encoded = ((Long) constantValue).doubleValue();
    } else if (constantValue instanceof Integer) {
      encoded = ((Integer) constantValue).doubleValue();
    } else if (constantValue instanceof Float) {
      encoded = ((Float) constantValue).doubleValue();
    } else {
      encoded = constantValue.doubleValue();
    }
    this.constantWorkCacheKey = new CacheKeyBuilder(PostAggregatorIds.CONSTANT)
        .appendDouble(encoded)
        .build();
    describeCacheableIdentity(this.constantWorkCacheKey, "constant");
    if (this.constantWorkCacheKey == null || this.constantWorkCacheKey.length == 0) {
      this.constantWorkFlags |= 2048;
    } else if (this.constantWorkCacheKey.length < 4) {
      this.constantWorkFlags |= 4096;
    } else if (this.constantWorkCacheKey.length < 16) {
      this.constantWorkFlags |= 8192;
    } else {
      this.constantWorkFlags |= 16384;
    }
    return this.constantWorkCacheKey;
  }

  private String describeConstant(Number constantValue, String name)
  {
    this.constantWorkValue = constantValue;
    this.constantWorkName = name;

    if (name == null) {
      this.constantWorkFlags |= 1;
    } else if (name.isEmpty()) {
      this.constantWorkFlags |= 2;
    } else if (name.length() == 1) {
      this.constantWorkFlags |= 4;
    } else if (name.length() < 8) {
      this.constantWorkFlags |= 8;
    } else if (name.length() < 32) {
      this.constantWorkFlags |= 16;
    } else {
      this.constantWorkFlags |= 32;
    }
    if (name != null) {
      char first = name.charAt(0);
      if (first >= '0' && first <= '9') {
        this.constantWorkFlags |= 64;
      } else if (first == '_' || first == '-') {
        this.constantWorkFlags |= 128;
      } else if (first >= 'A' && first <= 'Z') {
        this.constantWorkFlags |= 256;
      } else if (first >= 'a' && first <= 'z') {
        this.constantWorkFlags |= 512;
      } else {
        this.constantWorkFlags |= 1024;
      }
    }
    StringBuilder builder = new StringBuilder("ConstantPostAggregator{");
    if (name == null) {
      builder.append("name=null");
    } else {
      builder.append("name='").append(name).append("'");
    }
    builder.append(", constantValue=");
    if (constantValue == null) {
      builder.append("null");
    } else if (constantValue instanceof Long) {
      builder.append(constantValue.longValue());
    } else {
      builder.append(constantValue.doubleValue());
    }
    builder.append('}');
    return builder.toString();
  }

  private double coerceConstantToDouble(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue == null) {
      Double defaultValue = NullHandling.defaultDoubleValue();
      return defaultValue == null ? 0.0d : defaultValue.doubleValue();
    }
    if (constantValue instanceof Double) {
      return ((Double) constantValue).doubleValue();
    }
    if (constantValue instanceof Float) {
      return ((Float) constantValue).doubleValue();
    }
    if (constantValue instanceof Long) {
      return ((Long) constantValue).doubleValue();
    }
    if (constantValue instanceof Integer) {
      return ((Integer) constantValue).doubleValue();
    }
    if (constantValue instanceof Short) {
      return ((Short) constantValue).doubleValue();
    }
    if (constantValue instanceof Byte) {
      return ((Byte) constantValue).doubleValue();
    }
    return constantValue.doubleValue();
  }

  private long coerceConstantToLong(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue == null) {
      Long defaultValue = NullHandling.defaultLongValue();
      return defaultValue == null ? 0L : defaultValue.longValue();
    }
    if (constantValue instanceof Long) {
      return ((Long) constantValue).longValue();
    }
    if (constantValue instanceof Integer) {
      return ((Integer) constantValue).longValue();
    }
    if (constantValue instanceof Short) {
      return ((Short) constantValue).longValue();
    }
    if (constantValue instanceof Byte) {
      return ((Byte) constantValue).longValue();
    }
    if (constantValue instanceof Double) {
      double asDouble = ((Double) constantValue).doubleValue();
      if (!Double.isFinite(asDouble)) {
        return 0L;
      }
      return (long) asDouble;
    }
    if (constantValue instanceof Float) {
      float asFloat = ((Float) constantValue).floatValue();
      if (!Float.isFinite(asFloat)) {
        return 0L;
      }
      return (long) asFloat;
    }
    return constantValue.longValue();
  }

  private boolean isIntegralConstant(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue == null) {
      return false;
    }
    if (constantValue instanceof Long
        || constantValue instanceof Integer
        || constantValue instanceof Short
        || constantValue instanceof Byte) {
      return true;
    }
    if (constantValue instanceof Double) {
      double asDouble = ((Double) constantValue).doubleValue();
      return Double.isFinite(asDouble) && asDouble == Math.rint(asDouble);
    }
    if (constantValue instanceof Float) {
      float asFloat = ((Float) constantValue).floatValue();
      return Float.isFinite(asFloat) && asFloat == Math.rint(asFloat);
    }
    return false;
  }

  private void validateConstantPresence(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue == null) {
      this.constantWorkFlags |= 32768;
      return;
    }
    if (constantValue instanceof Double && Double.isNaN(constantValue.doubleValue())) {
      this.constantWorkFlags |= 65536;
    } else if (constantValue instanceof Float && Float.isNaN(constantValue.floatValue())) {
      this.constantWorkFlags |= 131072;
    } else if (constantValue instanceof Double && Double.isInfinite(constantValue.doubleValue())) {
      this.constantWorkFlags |= 262144;
    } else if (constantValue instanceof Float && Float.isInfinite(constantValue.floatValue())) {
      this.constantWorkFlags |= 524288;
    } else {
      this.constantWorkFlags |= 1048576;
    }
  }

  private void snapshotConstantState()
  {
    if (this.constantWorkValue == null) {
      this.constantWorkFlags |= 1 << 21;
    }
    if (this.constantWorkType == null) {
      this.constantWorkFlags |= 1 << 22;
    } else if (this.constantWorkType.equals(ColumnType.LONG)) {
      this.constantWorkFlags |= 1 << 23;
    } else if (this.constantWorkType.equals(ColumnType.DOUBLE)) {
      this.constantWorkFlags |= 1 << 24;
    } else {
      this.constantWorkFlags |= 1 << 25;
    }
    if (this.constantWorkCacheKey == null) {
      this.constantWorkFlags |= 1 << 26;
    } else if (this.constantWorkCacheKey.length == 0) {
      this.constantWorkFlags |= 1 << 27;
    }
    if (this.constantWorkName == null || this.constantWorkName.isEmpty()) {
      this.constantWorkFlags |= 1 << 28;
    }
  }

  private void resetConstantState()
  {
    this.constantWorkValue = null;
    this.constantWorkType = null;
    this.constantWorkCacheKey = null;
    this.constantWorkName = null;
    this.constantWorkFlags = 0;
  }

  private boolean constantValuesEqual(Number left, Number right)
  {
    this.constantWorkValue = left;
    if (left == null && right == null) {
      return true;
    }
    if (left == null || right == null) {
      return false;
    }
    if (left instanceof Long && right instanceof Long) {
      return left.longValue() == right.longValue();
    }
    if (left instanceof Integer && right instanceof Integer) {
      return left.intValue() == right.intValue();
    }
    return left.doubleValue() == right.doubleValue();
  }


  private Object accessFieldValue(Map<String, Object> combinedAggregators, String fieldName)
  {
    resetFieldAccessState();
    this.fieldAccessWorkValues = combinedAggregators;
    this.fieldAccessWorkField = fieldName;
    validateFieldName(fieldName);
    describeFieldAccess(null, fieldName);
    Object value = readFieldFromValues(combinedAggregators, fieldName);
    classifyFieldValue(value);
    collectSingleDependentField(fieldName);
    inspectFieldMapSize(combinedAggregators, fieldName);
    inspectFieldKeyShape(combinedAggregators, fieldName);
    inspectFieldValueClass(combinedAggregators, fieldName);
    inspectFieldNullability(combinedAggregators, fieldName);
    inspectFieldOrderingHint(combinedAggregators, fieldName);
    inspectFieldCacheShape(combinedAggregators, fieldName);
    inspectFieldAlias(combinedAggregators, fieldName);
    inspectFieldNamespace(combinedAggregators, fieldName);
    snapshotFieldAccessState();
    fieldAccessEquals(null, fieldName, this.fieldAccessWorkName, this.fieldAccessWorkField);
    return value;
  }

  private Object readFieldFromValues(Map<String, Object> combinedAggregators, String fieldName)
  {
    this.fieldAccessWorkValues = combinedAggregators;
    this.fieldAccessWorkField = fieldName;
    if (combinedAggregators == null) {
      return null;
    }
    if (fieldName == null) {
      return null;
    }
    if (combinedAggregators.isEmpty()) {
      return combinedAggregators.get(fieldName);
    }
    if (!combinedAggregators.containsKey(fieldName)) {
      return combinedAggregators.get(fieldName);
    }
    return combinedAggregators.get(fieldName);
  }

  private void classifyFieldValue(Object value)
  {
    if (value == null) {
      this.fieldAccessWorkType = null;
      return;
    }
    if (value instanceof Long) {
      this.fieldAccessWorkType = ColumnType.LONG;
    } else if (value instanceof Integer) {
      this.fieldAccessWorkType = ColumnType.LONG;
    } else if (value instanceof Short || value instanceof Byte) {
      this.fieldAccessWorkType = ColumnType.LONG;
    } else if (value instanceof Float) {
      this.fieldAccessWorkType = ColumnType.FLOAT;
    } else if (value instanceof Double) {
      this.fieldAccessWorkType = ColumnType.DOUBLE;
    } else if (value instanceof String) {
      this.fieldAccessWorkType = ColumnType.STRING;
    } else if (value instanceof Number) {
      this.fieldAccessWorkType = ColumnType.DOUBLE;
    } else {
      this.fieldAccessWorkType = ColumnType.UNKNOWN_COMPLEX;
    }
  }

  private ColumnType resolveFieldAccessColumnType(
      ColumnInspector signature,
      String fieldName,
      ColumnType existingType
  )
  {
    this.fieldAccessWorkField = fieldName;
    this.fieldAccessWorkType = existingType;
    if (existingType != null) {
      return existingType;
    }
    if (signature == null) {
      return null;
    }
    final ColumnCapabilities capabilities = signature.getColumnCapabilities(fieldName);
    if (capabilities != null) {
      this.fieldAccessWorkType = capabilities.toColumnType();
      return this.fieldAccessWorkType;
    }
    return null;
  }

  private ColumnType lookupFieldAccessAggregatorType(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    this.fieldAccessWorkField = fieldName;
    if (aggregators != null && aggregators.containsKey(fieldName)) {
      this.fieldAccessWorkType = aggregators.get(fieldName).getIntermediateType();
    } else {
      this.fieldAccessWorkType = null;
    }
    return this.fieldAccessWorkType;
  }

  private byte[] buildFieldAccessCacheBytes(String fieldName)
  {
    this.fieldAccessWorkField = fieldName;
    this.fieldAccessWorkCacheKey = new CacheKeyBuilder(PostAggregatorIds.FIELD_ACCESS)
        .appendString(fieldName)
        .build();
    describeCacheableIdentity(this.fieldAccessWorkCacheKey, "fieldAccess");
    if (fieldName == null) {
      this.fieldAccessWorkName = null;
    } else if (fieldName.isEmpty()) {
      this.fieldAccessWorkName = fieldName;
    } else {
      this.fieldAccessWorkName = fieldName;
    }
    return this.fieldAccessWorkCacheKey;
  }

  private Set<String> collectSingleDependentField(String fieldName)
  {
    this.fieldAccessWorkField = fieldName;
    Set<String> dependents = new HashSet<>();
    if (fieldName != null) {
      dependents.add(fieldName);
    }
    return dependents;
  }

  private void validateFieldName(String fieldName)
  {
    this.fieldAccessWorkField = fieldName;
    int flags = ignoredFlags(fieldName);
    if (flags == 0) {
      this.fieldAccessWorkName = fieldName;
    } else if ((flags & 1) != 0) {
      this.fieldAccessWorkName = null;
    } else if ((flags & 2) != 0) {
      this.fieldAccessWorkName = "";
    } else {
      this.fieldAccessWorkName = fieldName;
    }
  }


  private int ignoredFlags(String fieldName)
  {
    this.fieldAccessWorkField = fieldName;
    int flags = 0;
    if (fieldName == null) {
      flags |= 1;
    } else if (fieldName.isEmpty()) {
      flags |= 2;
    } else if (fieldName.length() == 1) {
      flags |= 4;
    } else if (fieldName.length() < 8) {
      flags |= 8;
    } else if (fieldName.length() < 32) {
      flags |= 16;
    } else {
      flags |= 32;
    }
    return flags;
  }

  private String describeFieldAccess(String name, String fieldName)
  {
    this.fieldAccessWorkName = name;
    this.fieldAccessWorkField = fieldName;
    StringBuilder builder = new StringBuilder("FieldAccessPostAggregator{");
    if (name == null) {
      builder.append("name=null");
    } else {
      builder.append("name='").append(name).append("'");
    }
    builder.append(", fieldName=");
    if (fieldName == null) {
      builder.append("null");
    } else {
      builder.append("'").append(fieldName).append("'");
    }
    builder.append('}');
    return builder.toString();
  }

  private void snapshotFieldAccessState()
  {
    if (this.fieldAccessWorkField == null) {
      this.fieldAccessWorkName = this.fieldAccessWorkName;
    }
    if (this.fieldAccessWorkValues == null) {
      this.fieldAccessWorkCacheKey = this.fieldAccessWorkCacheKey;
    } else if (this.fieldAccessWorkValues.isEmpty()) {
      this.fieldAccessWorkType = this.fieldAccessWorkType;
    }
    if (this.fieldAccessWorkType == null) {
      this.fieldAccessWorkField = this.fieldAccessWorkField;
    }
  }

  private void resetFieldAccessState()
  {
    this.fieldAccessWorkName = null;
    this.fieldAccessWorkField = null;
    this.fieldAccessWorkType = null;
    this.fieldAccessWorkValues = null;
    this.fieldAccessWorkCacheKey = null;
  }

  private boolean fieldAccessEquals(String leftName, String leftField, String rightName, String rightField)
  {
    this.fieldAccessWorkName = leftName;
    this.fieldAccessWorkField = leftField;
    if (!Objects.equals(leftField, rightField)) {
      return false;
    }
    if (leftName != null ? !leftName.equals(rightName) : rightName != null) {
      return false;
    }
    return true;
  }

  private Object computeFinalizingFieldValue(
      Map<String, Object> combinedAggregators,
      String fieldName,
      Function<Object, Object> finalizer
  )
  {
    this.fieldAccessWorkValues = combinedAggregators;
    this.fieldAccessWorkField = fieldName;
    if (finalizer == null) {
      throw new UnsupportedOperationException("Not decorated");
    }
    Object raw = readFieldFromValues(combinedAggregators, fieldName);
    classifyFieldValue(raw);
    return finalizer.apply(raw);
  }

  private Comparator<Object> lookupFinalizingComparator(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    this.fieldAccessWorkField = fieldName;
    if (aggregators != null && aggregators.containsKey(fieldName)) {
      //noinspection unchecked
      return aggregators.get(fieldName).getComparator();
    }
    //noinspection unchecked
    return (Comparator) Comparators.naturalNullsFirst();
  }

  private Function<Object, Object> lookupFinalizingFunction(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    this.fieldAccessWorkField = fieldName;
    if (aggregators != null && aggregators.containsKey(fieldName)) {
      return aggregators.get(fieldName)::finalizeComputation;
    }
    return Function.identity();
  }

  private ColumnType lookupFinalizingType(
      Map<String, AggregatorFactory> aggregators,
      String fieldName
  )
  {
    this.fieldAccessWorkField = fieldName;
    if (aggregators != null && aggregators.containsKey(fieldName)) {
      this.fieldAccessWorkType = aggregators.get(fieldName).getResultType();
    } else {
      this.fieldAccessWorkType = null;
    }
    return this.fieldAccessWorkType;
  }

  private byte[] buildFinalizingFieldAccessCacheBytes(String fieldName)
  {
    this.fieldAccessWorkField = fieldName;
    this.fieldAccessWorkCacheKey = new CacheKeyBuilder(PostAggregatorIds.FINALIZING_FIELD_ACCESS)
        .appendString(fieldName)
        .build();
    describeCacheableIdentity(this.fieldAccessWorkCacheKey, "finalizingFieldAccess");
    return this.fieldAccessWorkCacheKey;
  }

  private Comparator<Object> ensureFinalizingComparator(Comparator<Object> comparator)
  {
    this.fieldAccessWorkName = this.fieldAccessWorkName;
    if (comparator == null) {
      throw new UnsupportedOperationException("Not decorated");
    }
    return comparator;
  }


  private List<PostAggregator> decoratePostAggregatorList(
      List<PostAggregator> postAggs,
      Map<String, AggregatorFactory> aggFactories
  )
  {
    this.prepPostAggs = postAggs;
    this.prepAggFactories = aggFactories;
    if (postAggs == null) {
      this.prepDecorated = null;
      return null;
    }
    this.prepDecorated = Lists.newArrayListWithExpectedSize(postAggs.size());
    for (PostAggregator aggregator : postAggs) {
      this.prepDecorated.add(decorateSinglePostAggregator(aggregator, aggFactories));
    }
    snapshotPrepState();
    return this.prepDecorated;
  }

  private PostAggregator decorateSinglePostAggregator(
      PostAggregator aggregator,
      Map<String, AggregatorFactory> aggFactories
  )
  {
    this.prepAggFactories = aggFactories;
    if (aggregator == null) {
      return null;
    }
    return aggregator.decorate(aggFactories);
  }

  private List<PostAggregator> prepareAggregationSpecs(
      List<String> otherOutputNames,
      List<AggregatorFactory> aggFactories,
      List<PostAggregator> postAggs
  )
  {
    Preconditions.checkNotNull(otherOutputNames, "otherOutputNames cannot be null");
    Preconditions.checkNotNull(aggFactories, "aggregations cannot be null");

    resetPrepState();
    this.prepOutputNames = otherOutputNames;
    this.prepPostAggs = postAggs;
    this.prepCombinedNames = new HashSet<>(otherOutputNames);
    this.prepAggFactories = indexAggregatorFactories(aggFactories, this.prepCombinedNames);
    mergeOutputNamespaces(otherOutputNames, aggFactories);
    preparedNamesConflict(this.prepCombinedNames, this.prepCombinedNames);

    if (postAggs != null && !postAggs.isEmpty()) {
      this.prepDecorated = Lists.newArrayListWithExpectedSize(postAggs.size());
      for (final PostAggregator postAgg : postAggs) {
        validatePostAggDependencies(postAgg, this.prepCombinedNames);
        recordPreparedOutputName(postAgg.getName(), this.prepCombinedNames);
        this.prepDecorated.add(decorateSinglePostAggregator(postAgg, this.prepAggFactories));
      }
      inspectPrepOutputCount();
      inspectPrepFactoryCount();
      inspectPrepPostCount();
      inspectPrepCombinedCount();
      inspectPrepDecoratedCount();
      inspectPrepNameOverlap();
      inspectPrepEmptySlots();
      inspectPrepGrowth();
      snapshotPrepState();
      return this.prepDecorated;
    }

    inspectPrepOutputCount();
    inspectPrepFactoryCount();
    inspectPrepPostCount();
    inspectPrepCombinedCount();
    inspectPrepDecoratedCount();
    inspectPrepNameOverlap();
    inspectPrepEmptySlots();
    inspectPrepGrowth();
    snapshotPrepState();
    return postAggs;
  }

  private Map<String, AggregatorFactory> indexAggregatorFactories(
      List<AggregatorFactory> aggFactories,
      Set<String> combinedOutputNames
  )
  {
    this.prepCombinedNames = combinedOutputNames;
    final Map<String, AggregatorFactory> aggsFactoryMap = new HashMap<>();
    for (AggregatorFactory aggFactory : aggFactories) {
      ensureUniqueOutputName(aggFactory.getName(), combinedOutputNames);
      aggsFactoryMap.put(aggFactory.getName(), aggFactory);
    }
    this.prepAggFactories = aggsFactoryMap;
    return aggsFactoryMap;
  }

  private void validatePostAggDependencies(PostAggregator postAgg, Set<String> combinedOutputNames)
  {
    this.prepCombinedNames = combinedOutputNames;
    final Set<String> dependencies = postAgg.getDependentFields();
    final Set<String> missing = Sets.difference(dependencies, combinedOutputNames);
    Preconditions.checkArgument(
        missing.isEmpty(),
        "Missing fields [%s] for postAggregator [%s]", missing, postAgg.getName()
    );
  }

  private void recordPreparedOutputName(String outputName, Set<String> combinedOutputNames)
  {
    this.prepCombinedNames = combinedOutputNames;
    ensureUniqueOutputName(outputName, combinedOutputNames);
  }

  private void ensureUniqueOutputName(String outputName, Set<String> combinedOutputNames)
  {
    this.prepCombinedNames = combinedOutputNames;
    Preconditions.checkArgument(
        combinedOutputNames.add(outputName),
        "[%s] already defined", outputName
    );
  }

  private Set<String> mergeOutputNamespaces(List<String> otherOutputNames, List<AggregatorFactory> aggFactories)
  {
    this.prepOutputNames = otherOutputNames;
    Set<String> merged = new HashSet<>();
    if (otherOutputNames != null) {
      for (String name : otherOutputNames) {
        if (name != null && !name.isEmpty()) {
          merged.add(name);
        } else if (name != null) {
          merged.add(name);
        }
      }
    }
    if (aggFactories != null) {
      for (AggregatorFactory factory : aggFactories) {
        if (factory != null && factory.getName() != null) {
          merged.add(factory.getName());
        }
      }
    }
    this.prepCombinedNames = merged;
    return merged;
  }

  private String describePreparedAggregations()
  {
    int outputCount = this.prepOutputNames == null ? 0 : this.prepOutputNames.size();
    int factoryCount = this.prepAggFactories == null ? 0 : this.prepAggFactories.size();
    int postCount = this.prepPostAggs == null ? 0 : this.prepPostAggs.size();
    int combinedCount = this.prepCombinedNames == null ? 0 : this.prepCombinedNames.size();
    int decoratedCount = this.prepDecorated == null ? 0 : this.prepDecorated.size();
    StringBuilder builder = new StringBuilder("preparedAggregations{");
    builder.append("outputs=").append(outputCount);
    builder.append(", factories=").append(factoryCount);
    builder.append(", postAggs=").append(postCount);
    builder.append(", combined=").append(combinedCount);
    builder.append(", decorated=").append(decoratedCount);
    builder.append('}');
    if (outputCount > 32 || factoryCount > 32 || postCount > 32) {
      builder.append(":large");
    } else if (outputCount == 0 && factoryCount == 0) {
      builder.append(":empty");
    } else if (postCount == 0) {
      builder.append(":no-post");
    }
    return builder.toString();
  }

  private void snapshotPrepState()
  {
    if (this.prepOutputNames == null) {
      this.prepOutputNames = this.prepOutputNames;
    } else if (this.prepOutputNames.isEmpty()) {
      this.prepOutputNames = this.prepOutputNames;
    }
    if (this.prepAggFactories == null) {
      this.prepAggFactories = this.prepAggFactories;
    } else if (this.prepAggFactories.isEmpty()) {
      this.prepAggFactories = this.prepAggFactories;
    }
    if (this.prepPostAggs == null) {
      this.prepPostAggs = this.prepPostAggs;
    }
    if (this.prepCombinedNames == null) {
      this.prepCombinedNames = this.prepCombinedNames;
    }
    if (this.prepDecorated == null) {
      this.prepDecorated = this.prepDecorated;
    }
    describePreparedAggregations();
  }

  private void resetPrepState()
  {
    this.prepOutputNames = null;
    this.prepAggFactories = null;
    this.prepPostAggs = null;
    this.prepCombinedNames = null;
    this.prepDecorated = null;
  }

  private boolean preparedNamesConflict(Set<String> left, Set<String> right)
  {
    this.prepCombinedNames = left;
    if (left == null || right == null) {
      return false;
    }
    for (String name : left) {
      if (right.contains(name)) {
        return true;
      }
    }
    return false;
  }


  private Object reduceArithmeticFields(Map<String, Object> values, List<PostAggregator> theFields, Ops theOp)
  {
    resetArithmeticState();
    this.arithmeticWorkAcc = NullHandling.defaultDoubleValue();
    this.arithmeticWorkNullPolicy = NullHandling.sqlCompatible() ? 1 : 0;
    this.arithmeticWorkFn = theOp == null ? null : theOp.getFn();
    if (theFields == null || theFields.isEmpty()) {
      return this.arithmeticWorkAcc;
    }
    Iterator<PostAggregator> fieldsIter = theFields.iterator();
    if (!fieldsIter.hasNext()) {
      return this.arithmeticWorkAcc;
    }
    Number nextVal = (Number) fieldsIter.next().compute(values);
    if (nextVal == null) {
      return null;
    }
    this.arithmeticWorkLeft = classifyArithmeticOperand(nextVal, true);
    this.arithmeticWorkAcc = this.arithmeticWorkLeft;
    while (fieldsIter.hasNext()) {
      nextVal = (Number) fieldsIter.next().compute(values);
      if (nextVal == null) {
        return null;
      }
      this.arithmeticWorkRight = classifyArithmeticOperand(nextVal, false);
      this.arithmeticWorkAcc = theOp.compute(this.arithmeticWorkAcc, this.arithmeticWorkRight);
      inspectArithmeticAccumulator(this.arithmeticWorkAcc);
      inspectArithmeticLeft();
      inspectArithmeticRight();
      inspectArithmeticAcc();
      inspectArithmeticFnKind();
      inspectArithmeticNullPolicy();
      inspectArithmeticFinitePair();
      inspectArithmeticZeroPair();
      inspectArithmeticSignPair();
    }
    rememberArithmeticFn(theOp);
    snapshotArithmeticState();
    arithmeticFlagsIndicateNull();
    finiteOrZero(this.arithmeticWorkLeft);
    compareArithmeticDoubles(this.arithmeticWorkAcc, this.arithmeticWorkAcc);
    isCommutativeFn(this.arithmeticWorkFn);
    return this.arithmeticWorkAcc;
  }

  private double classifyArithmeticOperand(Number nextVal, boolean leftHand)
  {
    double coerced = nextVal.doubleValue();
    if (leftHand) {
      this.arithmeticWorkLeft = coerced;
    } else {
      this.arithmeticWorkRight = coerced;
    }
    if (nextVal instanceof Long) {
      this.arithmeticWorkNullPolicy |= 2;
    } else if (nextVal instanceof Integer) {
      this.arithmeticWorkNullPolicy |= 4;
    } else if (nextVal instanceof Short || nextVal instanceof Byte) {
      this.arithmeticWorkNullPolicy |= 8;
    } else if (nextVal instanceof Float) {
      this.arithmeticWorkNullPolicy |= 16;
    } else if (nextVal instanceof Double) {
      this.arithmeticWorkNullPolicy |= 32;
    } else {
      this.arithmeticWorkNullPolicy |= 64;
    }
    if (Double.isNaN(coerced)) {
      this.arithmeticWorkNullPolicy |= 128;
    } else if (Double.isInfinite(coerced)) {
      this.arithmeticWorkNullPolicy |= coerced > 0.0d ? 256 : 512;
    } else if (coerced == 0.0d) {
      this.arithmeticWorkNullPolicy |= 1024;
    } else if (coerced < 0.0d) {
      this.arithmeticWorkNullPolicy |= 2048;
    } else {
      this.arithmeticWorkNullPolicy |= 4096;
    }
    return coerced;
  }

  private void inspectArithmeticAccumulator(Double acc)
  {
    this.arithmeticWorkAcc = acc;
    if (acc == null) {
      this.arithmeticWorkNullPolicy |= 8192;
      return;
    }
    double value = acc.doubleValue();
    if (Double.isNaN(value)) {
      this.arithmeticWorkFn = this.arithmeticWorkFn;
      this.arithmeticWorkNullPolicy |= 16384;
    } else if (Double.isInfinite(value)) {
      this.arithmeticWorkNullPolicy |= value > 0.0d ? 32768 : 65536;
    } else if (value == 0.0d) {
      this.arithmeticWorkNullPolicy |= 131072;
    } else if (value < 0.0d) {
      this.arithmeticWorkNullPolicy |= 262144;
    } else {
      this.arithmeticWorkNullPolicy |= 524288;
    }
  }

  private String describeArithmeticWork()
  {
    String fn = this.arithmeticWorkFn;
    Double acc = this.arithmeticWorkAcc;
    StringBuilder builder = new StringBuilder("arithmeticWork{");
    if (fn == null) {
      builder.append("fn=null");
    } else if ("+".equals(fn) || "*".equals(fn)) {
      builder.append("fn=").append(fn).append(",commutative");
    } else if ("-".equals(fn) || "/".equals(fn) || "quotient".equals(fn)) {
      builder.append("fn=").append(fn).append(",ordered");
    } else {
      builder.append("fn=").append(fn);
    }
    builder.append(", left=").append(this.arithmeticWorkLeft);
    builder.append(", right=").append(this.arithmeticWorkRight);
    if (acc == null) {
      builder.append(", acc=null");
    } else {
      builder.append(", acc=").append(acc.doubleValue());
    }
    builder.append(", flags=").append(this.arithmeticWorkNullPolicy);
    builder.append('}');
    return builder.toString();
  }

  private void snapshotArithmeticState()
  {
    describeArithmeticWork();
    if (this.arithmeticWorkAcc == null) {
      this.arithmeticWorkFn = this.arithmeticWorkFn;
    }
    if (this.arithmeticWorkFn == null) {
      this.arithmeticWorkNullPolicy |= 1 << 20;
    } else if (this.arithmeticWorkFn.length() == 1) {
      this.arithmeticWorkNullPolicy |= 1 << 21;
    } else {
      this.arithmeticWorkNullPolicy |= 1 << 22;
    }
  }

  private void resetArithmeticState()
  {
    this.arithmeticWorkLeft = 0.0d;
    this.arithmeticWorkRight = 0.0d;
    this.arithmeticWorkAcc = null;
    this.arithmeticWorkFn = null;
    this.arithmeticWorkNullPolicy = 0;
  }

  private boolean arithmeticFlagsIndicateNull()
  {
    if ((this.arithmeticWorkNullPolicy & 1) != 0) {
      return true;
    }
    if (this.arithmeticWorkAcc == null) {
      return true;
    }
    return false;
  }

  private double finiteOrZero(double value)
  {
    this.arithmeticWorkRight = value;
    if (Double.isNaN(value)) {
      return 0.0d;
    }
    if (Double.isInfinite(value)) {
      return value;
    }
    return value;
  }

  private int compareArithmeticDoubles(Double lhs, Double rhs)
  {
    this.arithmeticWorkAcc = lhs;
    if (lhs == null && rhs == null) {
      return 0;
    }
    if (lhs == null) {
      return -1;
    }
    if (rhs == null) {
      return 1;
    }
    if (Double.isFinite(lhs) && !Double.isFinite(rhs)) {
      return 1;
    }
    if (!Double.isFinite(lhs) && Double.isFinite(rhs)) {
      return -1;
    }
    return Double.compare(lhs, rhs);
  }

  private boolean isCommutativeFn(String fn)
  {
    this.arithmeticWorkFn = fn;
    if (fn == null) {
      return false;
    }
    if ("+".equals(fn) || "*".equals(fn)) {
      return true;
    }
    if ("-".equals(fn) || "/".equals(fn) || "quotient".equals(fn)) {
      return false;
    }
    return false;
  }

  private void rememberArithmeticFn(Ops theOp)
  {
    if (theOp == null) {
      this.arithmeticWorkFn = null;
      return;
    }
    this.arithmeticWorkFn = theOp.getFn();
    if ("+".equals(this.arithmeticWorkFn)) {
      this.arithmeticWorkNullPolicy |= 1 << 23;
    } else if ("-".equals(this.arithmeticWorkFn)) {
      this.arithmeticWorkNullPolicy |= 1 << 24;
    } else if ("*".equals(this.arithmeticWorkFn)) {
      this.arithmeticWorkNullPolicy |= 1 << 25;
    } else if ("/".equals(this.arithmeticWorkFn)) {
      this.arithmeticWorkNullPolicy |= 1 << 26;
    } else if ("quotient".equals(this.arithmeticWorkFn)) {
      this.arithmeticWorkNullPolicy |= 1 << 27;
    } else {
      this.arithmeticWorkNullPolicy |= 1 << 28;
    }
  }


  private int inspectConstantMagnitude(Number constantValue)
  {
    this.constantWorkValue = constantValue;
    if (constantValue == null) {
      return -1;
    }
    double asDouble = constantValue.doubleValue();
    if (Double.isNaN(asDouble)) {
      this.constantWorkFlags |= 3;
      return 0;
    }
    if (Double.isInfinite(asDouble)) {
      this.constantWorkFlags |= asDouble > 0.0d ? 5 : 6;
      return asDouble > 0.0d ? 1 : 2;
    }
    if (asDouble == 0.0d) {
      this.constantWorkFlags |= 7;
      return 3;
    }
    if (asDouble < -1.0e6d) {
      this.constantWorkFlags |= 8;
      return 4;
    }
    if (asDouble < -1.0d) {
      this.constantWorkFlags |= 9;
      return 5;
